insert into public.academy_course_structures
    (app_slug, tier, structure, content_version)
insert into public.academy_quiz_questions
    (app_slug, tier, scope, module_key, ord, prompt, options, answer_index, explanation)
values
  ('riskchange', 'beginner', 'module', 'm01-what-these-engines-decide', 1, 'In the Suite, the Risk Register and its Heatmap tab both call one engine. Which engine is it?', '["calendar", "riskScoring", "lessonsLearned", "managementOfChange"]'::jsonb, 1, 'The Risk Register with its Heatmap tab calls riskScoring. Management of Change calls managementOfChange, Peer Review Manager calls peerReview and Lessons Learned calls lessonsLearned. All four apps read calendar dates through calendar.js.'),
  ('riskchange', 'beginner', 'module', 'm01-what-these-engines-decide', 2, 'What does the riskScoring engine itself keep about the risks it scores?', '["The last band it derived for each risk, so that a screen can read it back without asking again.", "The likelihood and impact of every risk, so that the app only has to send the risk''s id.", "A history of every band each risk has carried, dated by the as-of date of each call.", "Nothing. The app stores the record and asks the engine what that record means."]'::jsonb, 3, 'None of the four engines stores anything. The app stores the record and the engine decides a state from it on each call, so a band is always a fresh answer about the record as it stands.'),
  ('riskchange', 'beginner', 'module', 'm01-what-these-engines-decide', 3, 'A user asks for the band beside a risk to be edited by hand, leaving the two levels as they are. What does this module teach about that request?', '["A band is always derived from the record by the engine, so it follows the levels and nobody edits it directly.", "A band may be overridden by the owner of the risk, and the override is kept until the next review date.", "A band may be edited, and the engine then recomputes the levels to match it.", "The band is a field the assessor types, and the engine only checks its spelling."]'::jsonb, 0, 'Every entry an engine returns is a STATE decided from a record. Change the likelihood and the band that follows is a fresh answer from the same rule, which is why the question to ask about a surprising band is which field of the record produced it.'),
  ('riskchange', 'beginner', 'module', 'm01-what-these-engines-decide', 4, 'Every date-dependent status this course quotes is true on one as-of date. Which date is it?', '["2026-09-30, a Wednesday", "Whatever date the machine clock reads when the page is opened", "2026-10-01, a Thursday", "2026-10-01, a Friday"]'::jsonb, 2, 'The digest''s first line fixes the as-of date at 2026-10-01, a Thursday, and every engine call that takes a date was handed that one explicitly. None of them read a clock.'),
  ('riskchange', 'beginner', 'module', 'm01-what-these-engines-decide', 5, 'A caller hands isReviewOverdue a risk and leaves the date argument out. Which date does the function answer for?', '["The as-of date of this course, 2026-10-01, which the engine carries as its default.", "The date the risk record was last saved, which the app passes along with the record.", "The date on the machine clock of whatever is running it.", "It refuses the call, naming the missing date."]'::jsonb, 2, 'Each function that takes a date has a parameter that defaults to the machine clock when the caller leaves it out. The answer looks complete, and it is an answer for whichever day the machine happens to be on.'),
  ('riskchange', 'beginner', 'module', 'm01-what-these-engines-decide', 6, 'In which argument position does isReviewOverdue in riskScoring take its date?', '["Argument 2", "Argument 1", "Argument 3", "It takes no date, and reads the status only"]'::jsonb, 0, 'The digest reads every signature: riskScoring''s isReviewOverdue takes its date as argument 2, and so does daysUntil in calendar. Both default that argument to the machine clock.'),
  ('riskchange', 'beginner', 'module', 'm01-what-these-engines-decide', 7, 'Two analysts open the same risk register a day apart. One reports a review as overdue and the other reports it on time, and neither wrote down a date. Which reading does this module give?', '["One of them must have a stale copy of the register, since the rule gives one answer for one record.", "The later reading is the right one, because a review status is always read on the latest date available.", "The earlier reading is the right one, because the engine locks a status on the first day it is asked.", "Both can be right, because a function that defaults to the clock answers a different question each day, and neither report can be checked."]'::jsonb, 3, 'A report that does not state its as-of date cannot be checked by anybody, including its author the next morning. Handing the date in explicitly makes the answer a property of two named inputs.'),
  ('riskchange', 'beginner', 'module', 'm01-what-these-engines-decide', 8, 'How many of managementOfChange''s functions take a date, as the digest reads them from the engine''s signatures?', '["4 functions", "7 functions", "6 functions", "1 function"]'::jsonb, 1, 'managementOfChange has 7 date-taking functions, peerReview has 4, lessonsLearned has 6, and riskScoring and calendar have 1 each. The digest reads them from each signature, a parameter that defaults to the machine clock.'),
  ('riskchange', 'beginner', 'module', 'm01-what-these-engines-decide', 9, 'When an engine in this course refuses a verdict, what shape does the answer take?', '["A thrown error, which the app catches and shows as a generic failure message.", "An object whose ok field is false, carrying a reason a user can act on.", "A score of 0, the value every engine in the course uses to mean it will not answer.", "An empty object, so the app has to work out for itself which input was missing."]'::jsonb, 1, 'Every verdict that can be refused comes back as an object with ok, and a refusal carries a reason. The four engines refuse in the same shape, so one place in an app can show any refusal from any register.'),
  ('riskchange', 'beginner', 'module', 'm01-what-these-engines-decide', 10, 'Which set lists the three declining answers this tier meets, one for a band, one for appetite and one for a date?', '["\"Low\", \"Not set\" and the as-of date", "\"None\", \"Within appetite\" and null", "0, \"Above appetite\" and -1", "\"None\", \"Not set\" and null"]'::jsonb, 3, 'A score with no basis bands "None", appetite with no basis reads "Not set", and a date that cannot be read parses to null. In each case the engine returns a named answer that means no answer and does not guess.'),
  ('riskchange', 'beginner', 'module', 'm01-what-these-engines-decide', 11, 'A register report groups "Not set" with "Within appetite" as a softer form of passing. What is wrong with that?', '["\"Not set\" is the engine declining to report a pass it has no basis for, so it belongs with neither answer.", "Nothing, since a risk with no target is carried at the organisation''s default appetite.", "It should be grouped with \"Above appetite\", since the engine treats a missing target as a failure to be reported.", "\"Not set\" only appears on closed risks, so it should be left out of the report."]'::jsonb, 0, '"Not set" keeps the gap in the record visible. A missing target read as a pass would put a risk inside appetite that nobody ever measured against anything.'),
  ('riskchange', 'beginner', 'module', 'm01-what-these-engines-decide', 12, 'A chart ranks the bands with "None" at the bottom, one step below "Low". What does the module say about that ranking?', '["It is right, since \"None\" covers the scores between 0 and the lower edge of \"Low\".", "It is right only for residual scores, which can fall below the bottom of the grid.", "It is wrong: \"None\" is the one band that means no score, so it is no grade at all.", "It is wrong because \"None\" sits above \"Critical\", for scores beyond the grid."]'::jsonb, 2, 'A likelihood of 2.5 against an impact of 4 scores 0 and bands "None" because a fraction is off the scale. Reading that as a very low risk would count an unscored risk as a scored one.'),
  ('riskchange', 'beginner', 'module', 'm01-what-these-engines-decide', 13, 'On a register where nobody has set a target on any risk, how many risks can read "Within appetite"?', '["Every risk whose residual band is \"Low\", since a low residual needs no target.", "None of them, however low their residual scores are.", "Every risk whose residual score is below its inherent score.", "All of them, until somebody enters a target that one of them exceeds."]'::jsonb, 1, 'Appetite compares the residual with the risk''s OWN target. With no target, or a target of zero, the answer is "Not set", so the target is one of the inputs people choose and the engine cannot supply.'),
  ('riskchange', 'beginner', 'module', 'm01-what-these-engines-decide', 14, 'An owner changes a risk''s status to "Closed" while the hazard is still on the facility. What happens to the risk''s review check?', '["It keeps being checked until the engine sees the hazard removed from the facility record.", "It is refused: the engine will not accept a \"Closed\" status on a risk with a review date.", "It carries on as before, because the engine reads the review date before the status.", "It stops being checked, because only a live risk carries a review obligation, whether or not the hazard has gone."]'::jsonb, 3, 'The status is set on the record by people and the engine applies the rule that goes with it. A "Closed" risk is not live, so it can never read review-overdue, and nothing in the engine checks whether closing it was right.'),
  ('riskchange', 'beginner', 'module', 'm01-what-these-engines-decide', 15, 'What does an engine in this course guarantee about the status it returns?', '["That the record it was handed describes the facility as it stands on the as-of date.", "That the levels on the record were chosen by somebody qualified to assess the risk.", "That the same record, target, date and population always give the same answer.", "That every risk it scores was reviewed before the as-of date."]'::jsonb, 2, 'An engine guarantees nothing about whether the record describes the facility. That part of assurance is done by the people who keep the register, and a status can only be as right as the record it was handed.'),
  ('riskchange', 'beginner', 'module', 'm02-the-matrix-and-its-bands', 1, 'How does riskScoring turn a likelihood level and an impact level into a score?', '["It adds the two levels and doubles the total, so the top cell reaches 20.", "It takes the larger of the two levels and squares it, so a single high axis dominates.", "It multiplies the two whole levels, each on a scale from 1 to 5.", "It averages the two levels."]'::jsonb, 2, 'The scale runs from 1 to 5 on each axis and a score is the product of the two levels. Likelihood 3 and impact 4 score 12, and that one multiplication is the whole scoring rule.'),
  ('riskchange', 'beginner', 'module', 'm02-the-matrix-and-its-bands', 2, 'A spreadsheet import delivers a likelihood as the text "3.0" against an impact of 4. What score and band does the engine return?', '["12, \"High\"", "0, \"None\", because text is off the scale", "3, \"Low\"", "It refuses the text with ok false and a reason"]'::jsonb, 0, 'A whole number written as text or with a decimal point is still that level. "3", " 3 " and "3.0" all score exactly as the number 3 does against an impact of 4: 12, "High".'),
  ('riskchange', 'beginner', 'module', 'm02-the-matrix-and-its-bands', 3, 'The value true arrives as a likelihood. Asked against an impact of 1, what does the engine show it reads true as?', '["Level 5, the top of the scale, so it scores 5", "No level, so it scores 0 and bands \"None\" as false does", "Level 3, the middle of the scale, so it scores 3", "Level 1, since true against an impact of 1 scores 1"]'::jsonb, 3, 'True against an impact of 1 scores 1, so true is read as level 1, and true against an impact of 5 scores 5, "Medium". False against an impact of 1 scores 0, "None". The register''s own form stores whole numbers, so this is a value the form never writes.'),
  ('riskchange', 'beginner', 'module', 'm02-the-matrix-and-its-bands', 4, 'Counted from the grid of twenty five cells, how many cells band "Medium"?', '["6 cells", "7 cells", "8 cells", "4 cells"]'::jsonb, 1, 'The grid gives "Critical" 6, "High" 4, "Medium" 7 and "Low" 8, and 6 plus 4 plus 7 plus 8 is 25, one band for every cell.'),
  ('riskchange', 'beginner', 'module', 'm02-the-matrix-and-its-bands', 5, 'How many distinct scores does the five by five grid hold?', '["25", "14", "11", "15"]'::jsonb, 1, 'The grid has twenty five cells and 14 distinct scores, because the same product sits in several cells, as 20 does at likelihood 4 impact 5 and at likelihood 5 impact 4. The 11 whole numbers from 1 to 25 that no cell holds make up the rest.'),
  ('riskchange', 'beginner', 'module', 'm02-the-matrix-and-its-bands', 6, 'Which of these whole numbers is the score of no cell on the grid?', '["18", "16", "20", "15"]'::jsonb, 0, 'No two whole levels from 1 to 5 multiply to 18, so it is one of the 11 numbers no cell holds: 7, 11, 13, 14, 17, 18, 19, 21, 22, 23, 24. 16 is 4 by 4, 20 is 4 by 5 and 15 is 3 by 5.'),
  ('riskchange', 'beginner', 'module', 'm02-the-matrix-and-its-bands', 7, 'A score of 26 reaches riskScoring, from somewhere other than two levels. Which band does it read?', '["\"Critical\", found by its lower edge of 15", "\"None\"", "It is refused as above the grid", "\"High\""]'::jsonb, 0, 'Each band is found by its LOWER edge only, so any score that reaches 15 is "Critical". The upper edge of 25 printed in the band table is a label rather than a limit, and this is a stated limit of the engine that the course grades nothing on.'),
  ('riskchange', 'beginner', 'module', 'm02-the-matrix-and-its-bands', 8, 'What band does a score of 14.5 read?', '["\"Critical\", after rounding up to 15", "\"None\", as a fraction is off the scale", "\"High\", by the lower edge at 10", "\"Low\""]'::jsonb, 2, '14.5 reaches the lower edge of "High" at 10 and falls short of "Critical" at 15, so it reads "High". A fraction as a LEVEL is off the scale, while a score is only ever compared with the lower edges.'),
  ('riskchange', 'beginner', 'module', 'm02-the-matrix-and-its-bands', 9, 'A score equals 10 exactly. How does the engine band it, and why?', '["\"Medium\", as lower edges are excluded.", "\"Medium\", as a tie goes down.", "\"Critical\", because 10 is the product of 5 and 2, which sits on the top row of the grid.", "\"High\", as a score equal to a lower edge belongs to that band."]'::jsonb, 3, 'Reading from the top, 10 does not reach 15 and does reach 10, so it is "High". There is no gap between bands: the upper edge of "Medium" at 9 sits one below the lower edge of "High".'),
  ('riskchange', 'beginner', 'module', 'm02-the-matrix-and-its-bands', 10, 'An assessor who cannot choose between 2 and 3 writes 2.5 as the likelihood, with impact 4. Which result follows?', '["A score of 0 and the band \"None\"", "A score of 12 and the band \"High\", after rounding 2.5 up to 3", "A score of 8 and the band \"Medium\", after rounding 2.5 down to 2", "10, \"High\""]'::jsonb, 0, 'The scale is five WHOLE levels. A fraction is off the scale and unscored, the same as a level of 6 or a blank, and the engine returns 0 and "None" rather than guessing which level the assessor meant.'),
  ('riskchange', 'beginner', 'module', 'm02-the-matrix-and-its-bands', 11, 'A likelihood of 6 is handed in against an impact of 4. What happens to it?', '["Capped at 5: 20, \"Critical\".", "It is unscored: 0 and \"None\".", "It is multiplied as given and scores 24, \"Critical\", by the lower edge.", "It is refused with ok false and the reason that 6 is above the scale."]'::jsonb, 1, 'The scale stops at 5. A 6 might be a typing error for 5 or a level from a company scale with more steps, and the engine does not know, so it does not pick. It returns a score of 0 and the band "None".'),
  ('riskchange', 'beginner', 'module', 'm02-the-matrix-and-its-bands', 12, 'Why is the band "None" kept apart from "Low" when both sit at the bottom of the scores?', '["Because \"None\" is kept for closed risks and \"Low\" for live ones, so it is a status and never a band.", "Because \"None\" covers the residual score and \"Low\" covers the inherent score of the same risk.", "So that an unscored risk can never be counted as a low one.", "So the heatmap has a fifth colour for scores above the grid."]'::jsonb, 2, '"None" is the one band that means no score. A score of zero or below reads "None", and keeping it apart means a risk the engine could not score cannot be mistaken for a small one.'),
  ('riskchange', 'beginner', 'module', 'm02-the-matrix-and-its-bands', 13, 'One risk sits at likelihood 5, impact 1 and another at likelihood 1, impact 5. What does their band fail to tell a reviewer?', '["Whether either of them is live, since the band depends on the status.", "Nothing, since two risks with the same score must be the same kind of risk.", "Which of the two axes carries the high level, since both score 5 and band \"Medium\".", "Which of them is unscored, since one of the two bands \"None\"."]'::jsonb, 2, 'The product does not care which axis a level sits on, so one likely and moderate risk and one rare and severe risk can share a score and a band. The register keeps both levels on the record for exactly that reason.'),
  ('riskchange', 'beginner', 'module', 'm02-the-matrix-and-its-bands', 14, 'A register row carries a score of 13 beside its two levels. What should a reviewer conclude?', '["Something other than the product of two whole levels produced it, although the engine still bands it \"High\".", "The risk sits between two cells, and the engine rounds it to 12 before banding it.", "The risk is unscored, because 13 is a score the engine reads as \"None\".", "Nothing, since 13 is an ordinary cell on the fourth row of the grid."]'::jsonb, 0, '13 is one of the 11 whole numbers from 1 to 25 that no cell holds, so the record cannot have come from two whole levels on this scale. The band looks normal, which is why the check has to multiply the levels.'),
  ('riskchange', 'beginner', 'module', 'm02-the-matrix-and-its-bands', 15, 'The band table prints 14 as the upper edge of "High", and 14 is a number no cell of the grid holds. What does that show about the printed upper edges?', '["They are ignored for \"High\" only, because 14 cannot be a product of two levels.", "They are limits, so a score above one reads \"None\" until the next band''s lower edge.", "They are the edges the engine tests first, before it reads any lower edge at all.", "They are labels for people; no score is tested against them."]'::jsonb, 3, 'The band is found by its lower edge alone, so the upper edge printed beside each floor is a label. A label can name a number the grid never produces, which is one more reason to read the lower edges only.'),
  ('riskchange', 'beginner', 'module', 'm03-residual-and-appetite', 1, 'The Risk Register stores one band per risk in a column called rating. Which band is it?', '["The residual band, since it is the risk as it stands with its controls", "The higher of the inherent and residual bands", "Whichever band the assessor last chose to save by hand, with the engine checking only its spelling", "The inherent band, written from the engine on every save"]'::jsonb, 3, 'rating is the INHERENT band and it always matches the inherent levels on the record. The residual band has to be read separately, and it is the residual score that appetite compares with the target.'),
  ('riskchange', 'beginner', 'module', 'm03-residual-and-appetite', 2, 'Appetite on a risk compares two values. Which two?', '["The inherent score and the risk''s own target", "The residual score and the risk''s own target", "The residual score and one target shared by the whole register", "The inherent score and the residual score, so a risk is within appetite when its controls lower it"]'::jsonb, 1, 'The question appetite asks is whether the organisation can live with the risk as it stands, with its controls in place, so it reads the RESIDUAL. The target is set by people for each risk.'),
  ('riskchange', 'beginner', 'module', 'm03-residual-and-appetite', 3, 'A risk has inherent likelihood 4 and impact 5. Its residual likelihood is 2 and its residual impact is left blank. What is its residual?', '["10, \"High\"", "0, \"None\", as the blank impact is read as zero", "20, \"Critical\", as the whole residual falls back to the inherent score", "2, \"Low\""]'::jsonb, 0, 'A residual axis that has not been assessed falls back to the inherent level on that axis alone. The blank impact becomes the inherent 5 and the assessed likelihood of 2 is kept: 2 times 5 is 10, "High".'),
  ('riskchange', 'beginner', 'module', 'm03-residual-and-appetite', 4, 'Take a risk scored 4 by 5 before controls. The assessor fills in only the residual impact, as 3, and leaves the likelihood empty. Which residual does the engine derive?', '["6, \"Medium\"", "15, \"Critical\", with the blank read as the top level", "12, \"High\", with the blank likelihood read as the inherent 4", "0, \"None\", because a residual with one blank axis is left unscored"]'::jsonb, 2, 'The blank likelihood falls back to the inherent 4 and the assessed impact of 3 is used, so the residual is 4 times 3, which is 12, "High". Each axis is decided separately.'),
  ('riskchange', 'beginner', 'module', 'm03-residual-and-appetite', 5, 'OB-03 is "Under Review" with inherent levels of 5 and 4. Neither residual axis has been assessed. What is its residual?', '["20, \"Critical\"", "0, \"None\", because nothing has been assessed", "It has no residual until one axis is assessed", "4, \"Low\""]'::jsonb, 0, 'Null, an absent key and a blank all mean "not assessed", and each unassessed axis falls back to its inherent level. So OB-03''s residual is 5 times 4, the same 20 as its inherent score: a risk whose controls have not been assessed is carried at its inherent level.'),
  ('riskchange', 'beginner', 'module', 'm03-residual-and-appetite', 6, 'An assessor enters a residual likelihood of 2.5 and a residual impact of 3 on a risk with inherent levels 4 and 5. What is the residual?', '["12, \"High\", with 2.5 falling back to the inherent 4", "9, \"Medium\", with 2.5 rounded to 3", "6, \"Medium\", with 2.5 rounded to 2 so that the reading stays cautious", "0, \"None\": the residual is unscored"]'::jsonb, 3, 'A residual axis that WAS assessed with a value off the scale does not fall back. It leaves the residual unscored, 0 and "None", because replacing a value somebody chose with a level they did not choose would hide their error.'),
  ('riskchange', 'beginner', 'module', 'm03-residual-and-appetite', 7, 'A residual likelihood of 7 is entered against a residual impact of 3. What does the engine do with the 7?', '["It caps the 7 at 5 and scores the residual 15, \"Critical\".", "It leaves the residual unscored, since 7 was assessed and is off the scale.", "It falls back to the inherent likelihood, because it treats 7 as a blank.", "It keeps it and scores 21, which bands \"Critical\"."]'::jsonb, 1, 'A likelihood of 7 is above the top level of 5. It is an assessed value, so it does not fall back, and the residual is 0, "None". The engine neither caps nor rounds.'),
  ('riskchange', 'beginner', 'module', 'm03-residual-and-appetite', 8, 'Why does the engine let a blank residual axis fall back and refuse to let an off-scale one do the same?', '["A blank is always a typing error, while an off-scale value is usually a deliberate choice.", "Falling back is allowed for likelihood only, and an off-scale value is usually on impact.", "A blank means nobody has looked yet, while an off-scale value means somebody looked and wrote something the scale cannot hold.", "An off-scale value would push the score above 25."]'::jsonb, 2, 'Falling back to the inherent level on an off-scale value would throw the assessor''s judgement away without telling anyone. Leaving the residual unscored keeps the problem visible where the owner can correct it to a whole level.'),
  ('riskchange', 'beginner', 'module', 'm03-residual-and-appetite', 9, 'A residual of 8 is compared with a target of 8. What is the appetite answer?', '["\"Above appetite\"", "\"Within appetite\"", "\"Not set\"", "\"Within appetite\" only when the inherent score is also 8"]'::jsonb, 1, 'A residual EQUAL to the target is within appetite. The target is the most residual risk the organisation will carry for that hazard, so reaching it exactly is still acceptable.'),
  ('riskchange', 'beginner', 'module', 'm03-residual-and-appetite', 10, 'A risk has a residual of 6 and a target of 0. What does appetite read?', '["\"Not set\", as if no target existed", "\"Above appetite\", as 6 is above 0", "\"Within appetite\"", "\"Above appetite\" for every risk with a residual band above \"Low\""]'::jsonb, 0, 'With no target, or a target of zero, or a residual that cannot be scored, the answer is "Not set". A target of zero reads the same way as a target nobody set.'),
  ('riskchange', 'beginner', 'module', 'm03-residual-and-appetite', 11, 'A risk''s residual cannot be scored, so its residual score is 0, and its target is 8. What does appetite read?', '["\"Within appetite\", because 0 is below 8", "\"Above appetite\", since an unscored residual is treated as a failure", "\"Within appetite\" until the residual is scored", "\"Not set\", with no residual to compare"]'::jsonb, 3, 'Appetite compares the residual score with the target, and an unscored residual leaves one side of that comparison empty. The engine gives the same "Not set" here as it gives for a missing target or a target of zero.'),
  ('riskchange', 'beginner', 'module', 'm03-residual-and-appetite', 12, 'OB-01 has a residual band of "High" and reads "Within appetite". OB-02 has a residual band of "Medium" and reads "Above appetite". How can both be right?', '["They cannot both be right, so one of the two targets must have been typed into the wrong row.", "Appetite reads the inherent band, which is higher on OB-02 than it is on OB-01.", "Each is measured against its own target: OB-01 has 10 against 10 and OB-02 has 8 against 6.", "OB-02 is closed, so its appetite is read from an older band."]'::jsonb, 2, 'A higher band does not mean a worse appetite answer. The band ranks risks against one another on a common scale, and appetite measures each one against the level the organisation set for that hazard.'),
  ('riskchange', 'beginner', 'module', 'm03-residual-and-appetite', 13, 'OB-06 has a residual of 4, "Low", and reads "Not set" for appetite. Which side of the comparison is missing?', '["The target: none has been set.", "The residual, which has not been assessed on either axis.", "Both sides, since a \"Low\" residual is never compared with anything.", "Neither: \"Not set\" is how the engine spells a pass on a \"Low\" residual."]'::jsonb, 0, 'OB-06 has a perfectly good residual and no target. It could well be acceptable, and the engine will not say so, because nobody has decided what acceptable means for this hazard. The fix is a target on the record.'),
  ('riskchange', 'beginner', 'module', 'm03-residual-and-appetite', 14, 'OB-08 has a target of 5 and reads "Not set" for appetite. What does its record need before it can have an appetite answer?', '["A target, because a target of 5 is below the lower edge of \"Medium\".", "A residual impact, because its impact axis was left blank.", "A residual likelihood that is a whole level from 1 to 5, because its 2.5 is off the scale.", "An inherent impact on the scale."]'::jsonb, 2, 'OB-08''s residual likelihood of 2.5 is off the scale, so its residual is 0, "None", and appetite has no residual to compare. OB-11 is the risk whose inherent impact of 6 is off the scale.'),
  ('riskchange', 'beginner', 'module', 'm03-residual-and-appetite', 15, 'Which of these does the engine read as a residual axis that has not been assessed?', '["A zero, a null or a blank form field", "Null, an absent key or a blank form field", "Any value off the scale, including a fraction", "A blank form field only, since a null on a residual axis is refused with a reason"]'::jsonb, 1, 'Null, an absent key and a blank form field all mean "not assessed", and each falls back to the inherent level on its own axis. A value off the scale is an assessment and leaves the residual unscored.'),
  ('riskchange', 'beginner', 'module', 'm04-the-calendar-date', 1, 'Counted by daysUntil from the as-of date 2026-10-01, how many days away is 2026-10-31?', '["31", "30", "29", "-30"]'::jsonb, 1, 'From 2026-10-01 to 2026-10-31 is the thirty days of October that follow the first, so daysUntil returns 30. The first of November, 2026-11-01, is one day further at 31.'),
  ('riskchange', 'beginner', 'module', 'm04-the-calendar-date', 2, 'What does daysUntil return for 2027-01-01, counted from 2026-10-01?', '["-92, as the date falls in another year", "60, as the calendar counts every month in the gap as exactly 30 days", "92, a positive count, as the date is still to come", "3, a count of the months between the two dates"]'::jsonb, 2, 'A date after the as-of date is positive, a date before it negative, and the as-of date itself 0. The first day of 2027 is 92 whole days after 2026-10-01.'),
  ('riskchange', 'beginner', 'module', 'm04-the-calendar-date', 3, 'A record carries the date 2025-10-01. Read on the as-of date, how many whole days lie between them, sign included?', '["-365", "365", "-1, one year expressed as a count of years", "null, as a date a year earlier is outside the window the calendar reads"]'::jsonb, 0, 'The sign is read first: a date already gone is negative. A date one year before 2026-10-01 is -365 days away.'),
  ('riskchange', 'beginner', 'module', 'm04-the-calendar-date', 4, 'OB-01, an "Open" risk, falls due for review on 2026-10-01, the as-of date itself. Which pair of answers does the engine give on that day?', '["0 days, and overdue, since the review has not happened", "-1 days, and overdue", "1 day, and not overdue, as the due date counts as the day before", "0 days, and not overdue"]'::jsonb, 3, 'A review is overdue only when days until is below zero. OB-01''s days until on 2026-10-01 is 0, and 0 is not below zero: the review is due today and the day is not over.'),
  ('riskchange', 'beginner', 'module', 'm04-the-calendar-date', 5, 'OB-02 is "Open" and its next review is 2026-09-30. On 2026-10-01, is its review overdue?', '["Yes: it is live and its days until is -1, below zero.", "No: one day late is inside a tolerance.", "No, because -1 rounds to 0 in whole days.", "Yes, but only in a zone behind UTC."]'::jsonb, 0, 'A risk review is overdue when the risk is LIVE and its review date has PASSED. OB-02 is "Open" and 2026-09-30 is -1 days from 2026-10-01, so on that date it is overdue in every time zone.'),
  ('riskchange', 'beginner', 'module', 'm04-the-calendar-date', 6, 'A "Closed" risk''s review date passed the day before the as-of date. The same risk, marked "Open", is asked the same question. What are the two overdue answers?', '["Closed: yes. Open: yes, as both dates are past.", "Closed: no. Open: no, as one day late is still read as on time.", "Closed: no, and Open: yes.", "Closed: yes. Open: no."]'::jsonb, 2, 'The test asks the status first. Only a live risk carries a review obligation, so the "Closed" copy is never overdue whatever its date, while the "Open" copy with days until of -1 is.'),
  ('riskchange', 'beginner', 'module', 'm04-the-calendar-date', 7, 'What is the parsed value of "2026-02-30" in calendar.js, and what is its days until from 2026-10-01?', '["2026-03-02, as the date rolls into March", "null, and null: an impossible date is no date at all", "2026-02-28, pulled back to the month''s end", "It is refused with a reason"]'::jsonb, 1, 'A date that does not exist is no date at all, and the engine never rolls an impossible date over into a real one. A rolled-over date would look valid and carry a sensible count, which is exactly what makes it dangerous.'),
  ('riskchange', 'beginner', 'module', 'm04-the-calendar-date', 8, 'A review date on a record reads "2026-13-01". How does the calendar module read it?', '["It rolls the thirteenth month into January of the next year.", "It reads the month as 1 and keeps the year, since 13 is taken as a typing slip.", "It keeps the year and reads the date as the first day of that year.", "It parses it to null."]'::jsonb, 3, 'A thirteenth month parses to null, the same as 30 February and the same as text such as "after the turnaround". The engine never guesses which real date was meant.'),
  ('riskchange', 'beginner', 'module', 'm04-the-calendar-date', 9, 'An "Open" risk carries a review date of 30 February. What are its days until and its review overdue answer on 2026-10-01?', '["Days until negative, overdue yes, since February is before October", "It is flagged overdue until a readable date replaces it", "Days until null, overdue yes, as an unreadable date is treated as late", "Days until null, overdue no"]'::jsonb, 3, 'A live risk with no readable review date is never review-overdue: the engine has no date to be late against, and nothing in it flags the missing date. The record needs a review date that exists.'),
  ('riskchange', 'beginner', 'module', 'm04-the-calendar-date', 10, 'A record holds the timestamp "2026-09-30T23:30:00Z". What calendar date does calendar.js read, and what is its days until from 2026-10-01?', '["2026-09-30, and -1", "2026-10-01, and 0, for a reader east of UTC", "2026-10-01 in some zones and 2026-09-30 in others, so the count depends on the reader", "It is refused, because a timestamp is not a calendar date"]'::jsonb, 0, 'A timestamp is read by its leading date only, the date its first ten characters name, whatever the zone the reader is in. So it is 2026-09-30 and -1 for every reader.'),
  ('riskchange', 'beginner', 'module', 'm04-the-calendar-date', 11, 'Why does a whole number of days separate any two dates the calendar module reads, in every time zone?', '["The module rounds every gap to the nearest whole day after converting both dates to UTC, so the hours cancel.", "The module reads both dates at noon UTC.", "Both the record''s date and the as-of date are read at local midnight from their leading YYYY-MM-DD.", "The module counts only working days, and those are always whole."]'::jsonb, 2, 'Because both sides are read by the same rule, the hours never enter the calculation. From 2026-10-01 to 2026-10-02 is 1 day wherever you stand, and a review due on a date is due on that calendar day in every office.'),
  ('riskchange', 'beginner', 'module', 'm04-the-calendar-date', 12, 'On 2026-10-01, how many live OBODO risks are review-overdue, and which are they?', '["3: OB-01, OB-02 and OB-05", "2: OB-02 and OB-05, both \"Open\" with a passed date", "1: OB-05 only", "4: OB-02, OB-05, OB-09 and OB-10"]'::jsonb, 1, 'OB-02 is -1 days from 2026-10-01 and OB-05 is -16, and both are "Open". OB-01 is due on the as-of date itself and is not among them, and OB-09 and OB-10 are not live.'),
  ('riskchange', 'beginner', 'module', 'm04-the-calendar-date', 13, 'OB-09 is "Draft" with no review date. Why does its review overdue answer read no?', '["Its status is not live, so the test never reaches the date.", "Its days until is null, and the engine reads a null count as zero days, which is not below zero.", "Drafts wait for a first review date.", "Its review date defaults to the as-of date, which is never overdue."]'::jsonb, 0, 'The rule asks the status first, and "Draft" is not live. A live risk with no review date also reads no, for the other reason: there is no date to be late against.'),
  ('riskchange', 'beginner', 'module', 'm04-the-calendar-date', 14, 'Which two conditions does the risk review overdue rule check, and in which order?', '["The date first, then the status", "Only that days until is below zero, whatever the status", "First the band, then the date", "First that the risk is live, then that days until is below zero"]'::jsonb, 3, 'The test asks the status first: only "Open", "Under Review", "Mitigated" and "Realized" risks can be overdue. Then the date: a review due on the as-of date, 0 days away, is not overdue.'),
  ('riskchange', 'beginner', 'module', 'm04-the-calendar-date', 15, 'OB-07 is "Realized", with its review set for 2026-10-02. Taking 2026-10-01 as the as-of date, which reading is right?', '["1, and overdue", "-1, and overdue", "1 day away, so its review is not overdue", "It has no review obligation, as \"Realized\" is not a live status"]'::jsonb, 2, '"Realized" is live, so the date is read. 2026-10-02 is 1 day after 2026-10-01, which is not below zero, so on 2026-10-01 its review is not overdue.'),
  ('riskchange', 'beginner', 'module', 'm05-the-register-as-a-whole', 1, 'Which four statuses does the risk engine treat as live?', '["\"Open\", \"Under Review\", \"Draft\" and \"Realized\", the four still awaiting a decision", "\"Open\" and \"Under Review\" only, the two the dashboard counts", "\"Open\", \"Under Review\", \"Mitigated\" and \"Realized\"", "\"Open\", \"Under Review\", \"Mitigated\" and \"Closed\", which together cover every risk that has ever been assessed"]'::jsonb, 2, 'Live statuses are the risks an organisation still carries. "Draft" is not yet a carried risk and "Closed" is one the organisation has stopped carrying, so those two are not live.'),
  ('riskchange', 'beginner', 'module', 'm05-the-register-as-a-whole', 2, 'Why is a "Mitigated" risk still in the live group?', '["Mitigation lowers the residual without removing the risk, so the organisation still carries it and its controls still need reviewing.", "Because its inherent band is always \"Critical\" or \"High\".", "Because it has not yet been given a target, so appetite cannot be read on it.", "It is live only until its next review date, after which the engine reads it as closed."]'::jsonb, 0, 'The hazard is still on the facility and the controls are what keep it at its residual level. The only statuses that leave the live group are "Draft" and "Closed".'),
  ('riskchange', 'beginner', 'module', 'm05-the-register-as-a-whole', 3, 'How many risks does the OBODO register hold, and how many of them are live?', '["12 risks, 8 of them live, as the dashboard counts", "12 risks, 10 of them live", "10 risks, all live, since drafts are not held in the register", "12 risks, 9 of them live"]'::jsonb, 1, 'The two that are not live are OB-09, "Draft", and OB-10, "Closed". 12 risks minus those 2 leaves the 10 live ones.'),
  ('riskchange', 'beginner', 'module', 'm05-the-register-as-a-whole', 4, 'Handed a list of risks, what does countByBand do about their statuses?', '["It drops every \"Draft\" and \"Closed\" risk before counting.", "It counts live risks only, unless the caller passes every risk.", "It refuses a list that holds a risk which is not live, and names that risk in its reason.", "Nothing: it counts whatever list it is handed."]'::jsonb, 3, 'countByBand does not filter by status. Which risks to hand over, and whether to count inherent or residual, are both choices the caller makes.'),
  ('riskchange', 'beginner', 'module', 'm05-the-register-as-a-whole', 5, 'Counted over every OBODO risk on the inherent band, how many are "Critical"?', '["4", "1", "6", "5"]'::jsonb, 3, 'OB-01, OB-02, OB-03, OB-08 and OB-10 have inherent scores of 15, 16, 20, 15 and 20, all "Critical". Every risk counted inherent reads 5, 3, 2, 1 and 1 across "Critical", "High", "Medium", "Low" and "None", which adds to 12.'),
  ('riskchange', 'beginner', 'module', 'm05-the-register-as-a-whole', 6, 'Between the count of every risk inherent and the count of live risks inherent, "Critical" drops from 5 to 4. Which risk left, and why?', '["OB-09, because it is \"Draft\"", "OB-10, because it is \"Closed\"", "OB-08, because its residual is unscored and so it is taken out of the live list", "OB-03, because it is \"Under Review\""]'::jsonb, 1, 'Only the list changed. OB-10 is "Closed" with an inherent score of 20, so it leaves the live count. OB-09 also leaves, from the "Low" column, which drops from 1 to 0.'),
  ('riskchange', 'beginner', 'module', 'm05-the-register-as-a-whole', 7, 'On the OBODO register, which of these four populations gives a "Critical" count of 1?', '["Live risks counted on the residual band, where OB-03 alone is \"Critical\"", "Live risks counted on the inherent band", "Every risk counted on the inherent band", "The Heatmap tab''s population"]'::jsonb, 0, 'The four populations give Critical counts of 5, 1, 4 and 1: every risk inherent, every risk residual, live risks inherent and live risks residual. Every risk counted residual also gives 1, and it is not offered here. The Heatmap tab plots the live risks inherent, which is 4. OB-03''s residual is 20 because neither residual axis is assessed.'),
  ('riskchange', 'beginner', 'module', 'm05-the-register-as-a-whole', 8, 'Across its four populations, the OBODO register gives Critical counts of 5, 1, 4 and 1. What decides which of those a tile shows?', '["Only the as-of date the count was run on.", "The band table, which differs between the inherent and residual scores.", "Two choices the caller makes: which risks to hand over, and whether to count inherent or residual.", "Which of the four counts the engine judges to be correct for the register, which it reports as the headline figure."]'::jsonb, 2, 'The same register gives 3 different values depending on those two choices. Each count is right for the question it answers, and a dashboard tile has to say which question that is.'),
  ('riskchange', 'beginner', 'module', 'm05-the-register-as-a-whole', 9, 'Which OBODO risks land in the "None" column when all twelve are counted on their residual scores?', '["2: OB-08 and OB-11", "1: OB-11", "2: OB-03 and OB-11, as neither has an assessed residual", "3: OB-06, OB-08 and OB-11"]'::jsonb, 0, 'OB-08 is unscored on the residual because 2.5 is not a whole level, and OB-11 because its impact of 6 leaves both of its scores at 0. OB-03 is counted "Critical", since its blank axes take the inherent levels.'),
  ('riskchange', 'beginner', 'module', 'm05-the-register-as-a-whole', 10, 'Why does countByBand return a fifth column, "None", beside the four bands?', '["So that closed risks can be counted apart from the live ones.", "It is where the engine puts risks above 25.", "So a reader can add \"None\" to \"Low\" to get the count of risks needing no action.", "So the columns still add to the length of the list, and an unscored risk stays visible."]'::jsonb, 3, 'OB-11 has no inherent score and must be counted somewhere. A report that shows only the four bands drops it without a trace, and a reader totalling those four columns finds one risk missing with no clue which.'),
  ('riskchange', 'beginner', 'module', 'm05-the-register-as-a-whole', 11, 'Which population does the Risk Register dashboard count, and on which score?', '["The four live statuses, inherent", "\"Open\" and \"Under Review\" risks, residual", "Only \"Open\" and \"Under Review\" risks, on the inherent score", "Every risk in the register on both scores, drafts and closed risks included, with the inherent count shown first"]'::jsonb, 2, 'The dashboard counts Open and Under Review risks and plots them INHERENT. The Heatmap tab plots the four live statuses INHERENT, and the Assurance hub counts live risks through countByBand.'),
  ('riskchange', 'beginner', 'module', 'm05-the-register-as-a-whole', 12, 'On OBODO the Heatmap tab reads "High" 3 and the dashboard reads "High" 1. Which risks make the difference?', '["OB-09 and OB-10, which are not live, and so the Heatmap tab leaves them out as well", "OB-04 and OB-07, which are live and outside the dashboard''s population", "OB-05 and OB-04, since the dashboard reads the residual band on those two rows", "OB-08 and OB-11"]'::jsonb, 1, 'The dashboard takes "Open" and "Under Review" only. OB-04 is "Mitigated" and OB-07 is "Realized", both live, both with an inherent band of "High", and 3 minus 2 is 1.'),
  ('riskchange', 'beginner', 'module', 'm05-the-register-as-a-whole', 13, 'What does the Assurance hub show for "Critical" on the OBODO register?', '["5 inherent and 1 residual, over every risk", "4 inherent and 1 residual, from countByBand called twice over the live risks", "4 inherent only", "1, the residual count, since the hub hides the inherent score"]'::jsonb, 1, 'The hub calls countByBand twice over the live risks, once inherent and once residual, and shows both. Those are the two live rows of the four populations.'),
  ('riskchange', 'beginner', 'module', 'm05-the-register-as-a-whole', 14, 'OB-05 is "Open" with levels 2 and 5, residual levels 1 and 5, and a target of 4. What does deriveRiskFields give?', '["Inherent 10, \"High\"; residual 5, \"Medium\"; \"Above appetite\"", "Inherent 10, \"High\"; residual 5, \"Medium\"; \"Within appetite\"", "Inherent 10, \"Medium\"; residual 5, \"Low\"; \"Above appetite\"", "Inherent 10, \"High\"; residual 4, \"Low\"; \"Within appetite\""]'::jsonb, 0, '2 times 5 is 10, which reaches the lower edge of "High". 1 times 5 is 5, which reaches the lower edge of "Medium". A residual of 5 is above a target of 4.'),
  ('riskchange', 'beginner', 'module', 'm05-the-register-as-a-whole', 15, 'Which band does the register store as OB-05''s rating?', '["\"Medium\", the residual band it reads today", "\"Above appetite\"", "\"High\", its inherent band", "Both bands, joined as \"High\" to \"Medium\""]'::jsonb, 2, 'rating is the INHERENT band, written from the engine on every save. OB-05''s inherent band is "High" while its residual band is "Medium", and appetite is a separate answer.'),
  ('riskchange', 'beginner', 'module', 'm06-the-associate-reading', 1, 'OB-02, a fatigue crack in a jetty loading arm, is "Open" at 4 by 4 with a residual likelihood of 2, a blank residual impact and a target of 6. Which row does the engine give on 2026-10-01?', '["Residual 2, \"Low\"; \"Within appetite\"; review overdue", "Residual 8, \"Medium\"; \"Above appetite\"; review overdue", "Residual 0, \"None\"; \"Not set\"; review not overdue", "Residual 8, \"Medium\"; \"Above appetite\"; review not overdue, as a blank axis suspends the review date"]'::jsonb, 1, 'The blank impact falls back to the inherent 4, so the residual is 2 times 4, which is 8, "Medium", above its target of 6. Its review date, 2026-09-30, is -1 days from the as-of date, so on 2026-10-01 it is overdue.'),
  ('riskchange', 'beginner', 'module', 'm06-the-associate-reading', 2, 'OB-08 is "Open" at 3 by 5 with a residual likelihood of 2.5, a residual impact of 5, a target of 5 and a review on 2026-11-30. Which reading holds on 2026-10-01?', '["Residual 15, \"Critical\"; \"Above appetite\"; its review is 60 days off", "Residual 10, \"High\"; \"Above appetite\"; its review is 60 days off", "Residual 0, \"None\"; \"Within appetite\"", "Residual 0, \"None\"; \"Not set\"; its review is 60 days off"]'::jsonb, 3, 'A fraction is off the scale and an assessed value does not fall back, so the residual is unscored and appetite has nothing to compare. 2026-11-30 is 60 days after 2026-10-01, so the review is not overdue on that date.'),
  ('riskchange', 'beginner', 'module', 'm06-the-associate-reading', 3, 'OB-01 and OB-08 share their inherent levels, 3 by 5, and both score 15, "Critical". Where do the two rows part?', '["In their residual inputs: OB-01 scores a residual of 10, \"High\", and OB-08''s residual is unscored.", "In their inherent bands, since the engine breaks a tie between equal scores by status.", "Nowhere, since two risks with the same inherent levels share every derived value.", "In their review dates only."]'::jsonb, 0, 'OB-01''s residual levels are 2 and 5, which score 10 against a target of 10, "Within appetite". OB-08''s residual likelihood of 2.5 leaves its residual at 0, "None", and its appetite "Not set".'),
  ('riskchange', 'beginner', 'module', 'm06-the-associate-reading', 4, 'Across the 10 live OBODO risks, how do the appetite answers divide?', '["4 \"Above appetite\", 4 \"Within appetite\" and 2 \"Not set\"", "3 \"Above appetite\" and 7 \"Within appetite\", as a missing target is read as a pass", "3 \"Above appetite\", 4 \"Within appetite\" and 3 \"Not set\"", "5 \"Above appetite\", 5 \"Within appetite\""]'::jsonb, 2, 'Above: OB-02, OB-03 and OB-05. Within: OB-01, OB-04, OB-07 and OB-12. Not set: OB-06, OB-08 and OB-11. The three counts add to the 10 live risks.'),
  ('riskchange', 'beginner', 'module', 'm06-the-associate-reading', 5, 'Subtracting the two engine scores, OB-08''s inherent minus residual is 15. What does that figure say about its controls?', '["That its controls remove all of the risk, which makes it the best-controlled live risk on the register.", "That its controls lower the risk by exactly one band.", "That the risk should move to \"Mitigated\", since the reduction reaches the \"Critical\" edge of 15.", "Nothing: it is the size of a gap in the record, since the residual is unscored."]'::jsonb, 3, 'OB-08 shows its whole inherent score as a reduction only because its residual is unscored. A subtraction over an unscored or unassessed value describes no control at all, so the two scores are read before the difference.'),
  ('riskchange', 'beginner', 'module', 'm06-the-associate-reading', 6, 'OB-03 shows an inherent minus residual of 0. Why?', '["Its residual is not assessed on either axis, so both fall back to the inherent levels.", "Its controls have been assessed as doing nothing on either axis.", "It is not live, so the engine sets the difference to 0.", "Its inherent score is off the scale."]'::jsonb, 0, 'OB-03''s residual axes are both null, so each falls back and the residual equals the inherent 20. OB-11 also shows 0, for a different reason: neither of its scores exists.'),
  ('riskchange', 'beginner', 'module', 'm06-the-associate-reading', 7, 'In the six-step method this module works on OBODO rows, what is written down before a single row is read?', '["The band table", "The population to be counted", "The as-of date", "The target of every risk, since appetite is the question the reading is meant to answer"]'::jsonb, 2, 'Every dated answer is true on the as-of date, and a status that cannot be dated cannot be checked. Scoring, the residual, appetite, status and date, and the population follow in that order.'),
  ('riskchange', 'beginner', 'module', 'm06-the-associate-reading', 8, 'Working the method on OB-03, which is "Under Review" at 5 by 4 with both residual axes null, a target of 12 and a review on 2026-11-15, what does step four give?', '["\"Within appetite\", since the residual has not been assessed yet", "\"Above appetite\", since the residual of 20 is above 12", "\"Not set\"", "\"Above appetite\", since the inherent band is \"Critical\" and appetite reads the inherent band"]'::jsonb, 1, 'Both residual axes fall back, so the residual is 20, "Critical", and 20 is above the target of 12. Appetite reads the residual, and an unassessed residual is still a scored one.'),
  ('riskchange', 'beginner', 'module', 'm06-the-associate-reading', 9, 'In how many of the four band-count populations does OB-03 count as "Critical"?', '["All four, since it is live and \"Critical\" on both scores", "Two: the inherent ones", "Two: the live ones", "One: live risks residual"]'::jsonb, 0, 'OB-03 is "Under Review", so it is in both live populations, and its inherent and residual scores are both 20. It is the one risk counted "Critical" in the residual rows, which read 1.'),
  ('riskchange', 'beginner', 'module', 'm06-the-associate-reading', 10, 'A capstone row has the same levels as an OBODO row you have worked. What does the worked method say to do?', '["Reuse the OBODO answer, since the rules are the same.", "Reuse the scores and recompute only the date.", "Reuse the OBODO answer unless the status differs, since only the status can change a band.", "Run the steps again on the new row."]'::jsonb, 3, 'OB-01 and OB-08 share their inherent levels inside one register and still differ in their residual and appetite answers. The method is what carries over, and a fraction is never rounded to rescue a band.'),
  ('riskchange', 'beginner', 'module', 'm06-the-associate-reading', 11, 'In the Associate tier, what does "overdue" mean?', '["A change has passed its target date.", "A live risk''s review date has passed.", "A risk''s score has passed its target.", "Any record whose date is on or before the as-of date."]'::jsonb, 1, 'In the next tier a change can be overdue against its target date, which is a different question about a different record. The word is named every time it is used.'),
  ('riskchange', 'beginner', 'module', 'm06-the-associate-reading', 12, 'In the Associate tier, "Closed" is one of two statuses that are not live. What is it a status of?', '["A change", "A review", "A risk", "A band, the one that means no score"]'::jsonb, 2, '"Closed" in this tier is a status of a risk, and "Draft" is the other status that is not live. In the next tier "Closed" is a stage of a change, one of its three final stages beside "Rejected" and "Cancelled", and a closed risk and a closed change are different things. Name which record the word is about every time.'),
  ('riskchange', 'beginner', 'module', 'm06-the-associate-reading', 13, 'Which of these carries over unchanged from this tier into the next one?', '["The as-of date, the calendar''s whole days, and a refusal shaped as ok with a reason", "The four live statuses, used as the stages of a change", "The per-axis fallback, applied to signatures", "The appetite answers"]'::jsonb, 0, 'Every dated status in the next tier is still true on 2026-10-01, dates are read by the same calendar, and a refused verdict is the same object in every engine.'),
  ('riskchange', 'beginner', 'module', 'm06-the-associate-reading', 14, 'Step five of the method, applied to OB-05 ("Open", review 2026-09-15) on the as-of date 2026-10-01: what does it find?', '["Date only: -16 days, so overdue", "Status only: \"Open\", so overdue", "Status then date: live, -16 days, but inside the tolerance a live risk is given, so not overdue", "Status then date: live, -16 days, so overdue"]'::jsonb, 3, 'Step five reads the status first and then the date. OB-05 is "Open", so the date is read, and -16 days from 2026-10-01 is below zero.'),
  ('riskchange', 'beginner', 'module', 'm06-the-associate-reading', 15, '"OBODO has 4 Critical risks." How does this tier say that sentence should be written so a reader can check it?', '["OBODO has 4 \"Critical\" risks on 2026-10-01.", "OBODO has 4 live risks with a \"Critical\" inherent band.", "OBODO has 4 \"Critical\" risks after controls.", "OBODO has 4 \"Critical\" risks, as the engine counted them on 2026-10-01."]'::jsonb, 1, 'A band count is only checkable with its population and its score written beside it. On OBODO the same register gives Critical counts of 5, 1, 4 and 1.'),
  ('riskchange', 'beginner', 'final', null, 1, 'Which Suite app calls the peerReview engine?', '["Lessons Learned", "Management of Change", "The Risk Register, through its Heatmap tab", "Peer Review Manager"]'::jsonb, 3, 'Peer Review Manager asks peerReview for a closure verdict on a review. riskScoring sits behind the Risk Register and its Heatmap tab, and Lessons Learned has an engine of its own.'),
  ('riskchange', 'beginner', 'final', null, 2, 'Measured by loading the module, how many exports does riskScoring carry, and how are they split?', '["7 exports, all of them functions", "15 exports: 8 functions and 7 frozen tables and constants", "15 exports: 7 functions and 8 frozen tables and constants", "34 exports: 15 functions and 19 frozen tables and constants"]'::jsonb, 2, 'riskScoring has 15 exports, 7 of them functions and 8 frozen tables and constants, one of which is the band table. The 34, 15 and 19 split belongs to managementOfChange.'),
  ('riskchange', 'beginner', 'final', null, 3, 'Of the inputs behind a risk''s status, which does the engine choose for itself?', '["None: the levels, residual levels, target, as-of date and population are all chosen by people.", "The target, which it sets from the inherent band whenever a risk owner leaves the field empty.", "The as-of date, which it always reads from the register''s own settings so every user sees one date.", "The population, which it filters by status before counting, so that drafts never reach a tile."]'::jsonb, 0, 'An engine decides a state from a record by a fixed rule, and everything that goes into the record, and every choice about which records to hand over and on what date, stays with people.'),
  ('riskchange', 'beginner', 'final', null, 4, 'A status report reads "OB-01 is not overdue." What does it need before anybody can check it?', '["OB-01''s band", "The date it is true on, 2026-10-01", "The name of the engine that produced it, so a reader can rerun the call", "Nothing, since a review status is the same on every day"]'::jsonb, 1, 'A status quoted without its date has lost half of what produced it. "OB-01 is not overdue on 2026-10-01" is the sentence that can be checked.'),
  ('riskchange', 'beginner', 'final', null, 5, 'Measured by loading the module, how many functions does calendar export, and how many of those take a date?', '["6 functions, and every one of them takes a date", "5 functions, and none takes a date, as the module only parses dates", "5 functions, and 1 of them takes a date", "1 function, daysUntil, beside 5 frozen tables and constants"]'::jsonb, 2, 'calendar has 6 exports: 5 functions and 1 frozen table or constant. Its one function that takes a date is daysUntil, which takes it as argument 2 and defaults it to the machine clock when the caller leaves it out.'),
  ('riskchange', 'beginner', 'final', null, 6, 'How many functions in lessonsLearned take a date, each defaulting it to the machine clock?', '["6 of its 26 functions", "All 26 of its functions", "4 of its 17 functions", "1, as in calendar"]'::jsonb, 0, 'lessonsLearned has 40 exports and 26 functions, and 6 of those functions take a date: daysUntil, isReviewDueSoon, isReviewOverdue, lessonAgeDays, lessonByAttention and summarise.'),
  ('riskchange', 'beginner', 'final', null, 7, 'A band beside a risk surprises its owner. Where does this tier say to look first?', '["At the field of the record that produced it", "At the engine version, since a band can change when the engine is updated", "At the band table, which each organisation edits", "At the machine clock, since bands move with the date"]'::jsonb, 0, 'The rule is the same for every user. What varies is the record, so the question to ask first is which field of the record produced the answer.'),
  ('riskchange', 'beginner', 'final', null, 8, 'Suppose 4.5 turns up in the score column of an imported register. Which band holds it?', '["\"Medium\", after rounding up to 5", "\"None\", as a fractional score is unscored", "It is refused, as no cell of the grid holds 4.5, so the engine will not band it", "\"Low\", as it reaches the lower edge of 1 and falls short of 5"]'::jsonb, 3, 'Reading down the floors, 4.5 passes under 5, where "Medium" starts, and clears 1, where "Low" starts. Only a fractional LEVEL is off the scale; a score just meets the floors.'),
  ('riskchange', 'beginner', 'final', null, 9, 'A score of -3 reaches the band table. Where does it land?', '["\"Low\", the lowest band on the table", "It is refused as negative", "\"None\" only when the likelihood was negative; a negative impact gives \"Low\"", "\"None\", as any score of zero or below means no score"]'::jsonb, 3, 'Zero and every negative score take "None". That label marks a missing score, so it sits outside the four real bands and out of every tally of low risks.'),
  ('riskchange', 'beginner', 'final', null, 10, 'A likelihood arrives as " 3 ", with a space either side, against an impact of 4. What does the engine make of it?', '["It is blank text, so it scores 0 and bands \"None\"", "Level 3, but it scores 0 until the spaces are removed by the app", "It is refused", "Level 3: it scores 12 and bands \"High\""]'::jsonb, 3, 'Padding round a whole level does not stop it being read as that level, so the product is 3 times 4. A spreadsheet that pads its cells gets the same band as one that does not.'),
  ('riskchange', 'beginner', 'final', null, 11, 'An import carries the boolean false in a likelihood field, and the impact is 1. What does riskScoring answer?', '["Nothing scored: 0, \"None\"", "A score of 1 and the band \"Low\"", "A refusal", "A score of 5 and the band \"Medium\", as false is read as the top of the scale"]'::jsonb, 0, 'The engine takes false as no level, so the product is 0 and the band is the one that means no score. True, handed in the same way, is taken as level 1. The register''s form writes neither.'),
  ('riskchange', 'beginner', 'final', null, 12, 'Where on the grid do the "Critical" cells sit, and how many are there?', '["8 cells, spread along the top row and down the right-hand column", "6 cells, all in the top right corner where both levels are high", "6 cells, all on the diagonal from bottom left to top right", "4 cells"]'::jsonb, 1, 'Counted from the grid, "Critical" has 6 cells, "High" 4, "Medium" 7 and "Low" 8. The "Critical" cells sit where both levels are high and the "Low" cells in the bottom left.'),
  ('riskchange', 'beginner', 'final', null, 13, 'Likelihood 4 with impact 3 and likelihood 3 with impact 4 are two different cells. What do they share?', '["Nothing, since each cell carries a score of its own", "The band only, since the two scores differ by the order of the levels", "The same risk, since a cell names a single kind of hazard", "The score 12 and the band \"High\""]'::jsonb, 3, 'The product does not care which axis a level sits on, so the same score appears in more than one cell. Two risks in those two cells can be very different hazards with the same band.'),
  ('riskchange', 'beginner', 'final', null, 14, 'An import writes the text "3.5" into a likelihood field, with impact 4. Which score and band follow?', '["A score of 12, \"High\", once the text is read as 3", "Unscored at 0, \"None\"", "A score of 14, \"High\"", "A score of 16, \"Critical\", once the text is rounded to 4"]'::jsonb, 1, 'Text is read as a level only when it names a whole level. "3.5" is a fraction written as text, and a fraction is off the scale and unscored, however it arrives.'),
  ('riskchange', 'beginner', 'final', null, 15, 'How many whole numbers from 1 to 25 does the grid never produce, and why?', '["14, since the grid holds only 11 distinct scores", "11, since no two whole levels from 1 to 5 multiply to any of them", "11, since each of them would need a level above 5 on both axes at the same time", "none"]'::jsonb, 1, 'Every product of two levels from 1 to 5 appears in some cell, and the 14 products that do appear leave 11 gaps between 1 and 25. The first gap is 7 and the last is 24.'),
  ('riskchange', 'beginner', 'final', null, 16, 'OB-04 is "Mitigated" with a residual of 9 and a target of 9. What is its appetite answer, and which rule decides it?', '["\"Above appetite\": a residual must fall below its target", "\"Not set\", since a mitigated risk carries no target", "\"Within appetite\" only because it is \"Mitigated\"", "\"Within appetite\": equal to the target counts as within"]'::jsonb, 3, 'A residual EQUAL to the target is within appetite, since the target is the most the organisation will carry for that hazard. OB-07 does the same with 8 against 8.'),
  ('riskchange', 'beginner', 'final', null, 17, 'A residual of 9 meets a target of 8. Which appetite answer follows?', '["\"Within appetite\", as 9 and 8 are both \"Medium\"", "\"Above appetite\": 9 exceeds 8", "\"Not set\", since a residual and a target in one band cannot be compared", "\"Within appetite\", as a residual within one of its target is tolerated"]'::jsonb, 1, 'Appetite compares the residual score with the target, and the bands play no part. A residual of 9 is over a target of 8, though both numbers band "Medium".'),
  ('riskchange', 'beginner', 'final', null, 18, 'Nobody has entered a target on a risk whose residual scores 6. Which appetite word does the engine print?', '["\"Within appetite\", since 6 is \"Medium\"", "\"Above appetite\" until a target is set", "\"Not set\"", "\"Within appetite\", since with no target any residual is accepted by default"]'::jsonb, 2, 'An empty target leaves the comparison with one side missing, and the engine prints its declining word in place of a pass or a fail. Against a target of 8 the same 6 would read "Within appetite".'),
  ('riskchange', 'beginner', 'final', null, 19, 'OB-11 has an impact of 6, no residual levels assessed and a target of 6. Why does its appetite read "Not set"?', '["Its impact is off the scale, so both its scores are 0", "Its target is missing, so appetite has nothing to compare against", "Its residual of 6 equals the target, which the engine reads as undecided", "It is not live"]'::jsonb, 0, 'An impact of 6 is beyond the top level, which leaves OB-11 without an inherent score, and its unassessed residual is 0, "None", too. Appetite then has nothing to set against the target of 6.'),
  ('riskchange', 'beginner', 'final', null, 20, 'OB-09 is "Draft" at 2 by 2 and neither residual axis is assessed. What residual does deriveRiskFields give it?', '["0, \"None\"", "4, \"Low\", with both axes falling back to the inherent 2", "It has none, since a draft risk is not scored", "2, \"Low\", with one axis falling back and the other left at 1"]'::jsonb, 1, 'Scoring does not depend on status. Both unassessed axes fall back to the inherent levels, so the residual is 2 times 2, which is 4, "Low", the same as its inherent score.'),
  ('riskchange', 'beginner', 'final', null, 21, 'OB-01''s rating column reads "Critical" while its residual band is "High". Which is right?', '["The residual, and the rating is stale", "The rating, as the residual is only an estimate", "Both: the rating is the inherent band, and the residual is a separate answer", "Neither, since a risk with two bands has been scored twice and needs its levels checking against the grid before either band can be quoted"]'::jsonb, 2, 'The stored column holds the band before controls, 3 by 5 giving 15. The band after controls, 2 by 5 giving 10, is a second answer to a second question, and neither overrides the other.'),
  ('riskchange', 'beginner', 'final', null, 22, 'On a count from the as-of date, where does 2026-11-01 fall?', '["30 days ahead", "61 days ahead", "31 days ahead", "1, one month"]'::jsonb, 2, 'October has 30 days after its first, which brings 2026-10-31 to 30, and one more day reaches 31. Each count is in whole days.'),
  ('riskchange', 'beginner', 'final', null, 23, 'What is daysUntil for 2026-10-02, counted from 2026-10-01, for a reader in any time zone?', '["1 everywhere", "1 in some zones and 0 in others", "0, as the date is read in UTC", "2"]'::jsonb, 0, 'Neither date carries an hour once it is read, so readers in any two offices count the same single day between them.'),
  ('riskchange', 'beginner', 'final', null, 24, 'OB-10 was marked "Closed" and still shows a review date of 2027-03-31. What does the register report for it on 2026-10-01?', '["181 days, and overdue, since a closed risk still carries its date", "181 days to go, and no overdue flag", "-181 days, and overdue, counted back from the review", "null, and not overdue, since a closed risk has no date"]'::jsonb, 1, 'daysUntil still counts the date, 181 days after 2026-10-01. The overdue test asks the status first, and a "Closed" risk is not live, so it can never read overdue whatever its date.'),
  ('riskchange', 'beginner', 'final', null, 25, 'A review date reads "after the turnaround". What does calendar.js parse it to?', '["The as-of date, as a stand-in", "The first day of the next month", "null", "The date of the next turnaround the register holds"]'::jsonb, 2, 'Words where a date should be parse to null, and so does a date that does not exist. The engine never guesses a day, so the gap stays visible on the record.'),
  ('riskchange', 'beginner', 'final', null, 26, 'How far is OB-03''s review, set for 2026-11-15, from the as-of date 2026-10-01?', '["-45", "60", "15", "45 days on"]'::jsonb, 3, 'A date still to come gives a positive count, and mid November is 45 whole days on. The figure is only checkable with the date it was counted from.'),
  ('riskchange', 'beginner', 'final', null, 27, 'What in riskScoring warns that a live risk has no review date at all?', '["isReviewOverdue returns ok false with a reason naming the missing date", "daysUntil returns -1 for a missing date, so the risk reads overdue at once", "The band drops to \"None\" until a review date is entered on the record", "Nothing: it reads not overdue, and nothing flags the missing date"]'::jsonb, 3, 'With no date there is nothing to fall behind, so the answer is no and no warning is raised. A person reading the register has to notice the empty field.'),
  ('riskchange', 'beginner', 'final', null, 28, 'Is OB-06, an "Open" risk due for review on 2026-10-31, late on 2026-10-01?', '["No: it has 30 days left", "Yes, because it has no target", "No, as \"Open\" risks are checked at month end only", "Yes: it is -30 days away"]'::jsonb, 0, 'OB-06 is live, so its date is read, and the end of October is still to come. Its missing target decides its appetite answer and has nothing to do with its review.'),
  ('riskchange', 'beginner', 'final', null, 29, 'An event on the register has actually happened, and the risk now reads "Realized". Does it stay in the live group?', '["Yes, because it still has a review date on the record, and any dated risk is live", "Yes: the organisation is living with its consequences and still carries it", "No: it leaves once its residual is assessed", "No, because the engine treats any status past \"Mitigated\" as finished, like \"Closed\""]'::jsonb, 1, 'The live group is the set of risks still carried. A realized risk cannot be put down by changing a word on its record, and its review date keeps counting.'),
  ('riskchange', 'beginner', 'final', null, 30, 'Counting every OBODO risk on its residual band, how many read "Medium"?', '["4 risks, the live count", "2 risks, the inherent count", "5 of the 12", "7 risks"]'::jsonb, 2, 'Every risk counted residual reads "Critical" 1, "High" 1, "Medium" 5, "Low" 3 and "None" 2. Over the live risks only, residual "Medium" is 4.'),
  ('riskchange', 'beginner', 'final', null, 31, 'Live OBODO risks counted inherent read "Low" 0. Why is the column empty?', '["No OBODO risk has an inherent score below 5", "countByBand drops the \"Low\" band from live counts", "The one risk with an inherent \"Low\" band, OB-09, is \"Draft\" and so is not live", "OB-06 and OB-12 moved to \"Low\" on the residual"]'::jsonb, 2, 'Every risk counted inherent has "Low" 1, OB-09 at 4. Handing over only live risks takes OB-09 out, and nothing else moves because the other risks are in both lists.'),
  ('riskchange', 'beginner', 'final', null, 32, 'How many OBODO risks does the Risk Register dashboard count?', '["10 risks, every live one", "12 risks, the whole register", "6 risks", "8 risks"]'::jsonb, 3, 'Its list is OB-01, OB-02, OB-03, OB-05, OB-06, OB-08, OB-11 and OB-12, read inherent: "Critical" 4, "High" 1, "Medium" 2, "Low" 0 and "None" 1.'),
  ('riskchange', 'beginner', 'final', null, 33, 'RECON records the Heatmap tab and the dashboard disagreeing. What does this tier say about which is miscounting?', '["The dashboard, which drops live risks that the Heatmap tab rightly counts as carried", "The Heatmap tab, which counts risks that are not live alongside the carried ones", "Neither: each counts the list it was given, and the lists differ by status", "Both, since two heatmaps of one register should agree in every cell they share"]'::jsonb, 2, 'The tab takes all four live statuses and the dashboard two of them, so a "Mitigated" or "Realized" risk shows on one and not the other. Each count is faithful to its own list.'),
  ('riskchange', 'beginner', 'final', null, 34, 'Why does deriveRiskFields produce every column of a row in one call?', '["Because the engine stores the row", "Because a band is read from the target", "So every column comes from the same record at the same moment and no column can drift from the others", "So the app can store all the columns and skip the engine next time"]'::jsonb, 2, 'The band cannot disagree with the score beside it, and the appetite cannot be computed from a residual that has since changed. Edit a level and derive the row again, and every column moves together.'),
  ('riskchange', 'beginner', 'final', null, 35, 'OB-12 is "Open" at 1 by 5, with residual levels 1 and 3 and a target of 3. Which row does the engine derive?', '["5, \"Medium\"; residual 3, \"Low\"; \"Within appetite\"", "5, \"Medium\"; residual 3, \"Low\"; \"Above appetite\"", "5, \"Low\"; residual 3, \"Low\"; \"Within appetite\"", "5, \"Medium\"; residual 15, \"Critical\"; \"Above appetite\""]'::jsonb, 0, 'Before controls the product lands on 5, the floor of "Medium". After controls it is 3, inside "Low", and 3 sits exactly on the target of 3.'),
  ('riskchange', 'beginner', 'final', null, 36, 'Take OB-07''s residual away from its inherent score. What is left?', '["0", "8", "12, its whole inherent score", "4, from 12 and 8"]'::jsonb, 3, 'OB-07 is 3 by 4 inherent, 12, and 2 by 4 residual, 8. Unlike OB-08, OB-11 and OB-03, both of its scores exist and its residual was assessed, so the difference rests on two real scores.'),
  ('riskchange', 'beginner', 'final', null, 37, 'What does the 0 in OB-11''s reduction column tell a reader about its controls?', '["Controls that do nothing on either axis of the risk", "Nothing: neither of its scores exists", "A risk that already sits exactly at its target of 6", "An assessed residual that equals the inherent score"]'::jsonb, 1, 'OB-11''s impact of 6 is off the scale, so its inherent and residual are both 0. OB-03 also shows 0, for another reason: its residual was not assessed and fell back.'),
  ('riskchange', 'beginner', 'final', null, 38, 'Applying step three of the method to OB-02, which residual axis falls back, and to what?', '["The impact, to the inherent 4, since its residual impact is blank", "The likelihood, to the inherent 4", "Neither, as a blank leaves the residual unscored", "Both axes, to 4 and 4"]'::jsonb, 0, 'Only the empty field is replaced. The assessed 2 on likelihood stays, the missing impact borrows OB-02''s inherent 4, and the product is 8, "Medium".'),
  ('riskchange', 'beginner', 'final', null, 39, 'Which inherent inputs leave a risk at 0, "None", in step two of the method?', '["A fraction, a 6, a blank or a negative on either axis", "Only a blank", "A fraction only, since a 6 is capped", "Any level below 3"]'::jsonb, 0, 'A whole number written as text is still that level, while a fraction, a 6, a blank or a negative is off the scale. The inherent axes have nothing to fall back to.'),
  ('riskchange', 'beginner', 'final', null, 40, 'What kind of answer does this tier warn the next one will often give?', '["A band", "A days-until count", "A refusal, with a reason a user can act on", "An appetite answer"]'::jsonb, 2, 'A risk is read; a change is moved. The next tier is about stages and legal moves, and when a move is not allowed the engine refuses it, and a refusal is read as carefully as a band.'),
  ('riskchange', 'beginner', 'final', null, 41, 'Which segregation of duties rule does this tier say the next one teaches?', '["The person who raised a change is not the one who approves it", "An assessor may not score their own risk", "A risk owner may not set their own target", "The person who closes a risk must be a different person from the one who wrote it, and from the reviewer"]'::jsonb, 0, 'A change is approved in levels, and the person who raised a change is not the person who approves it. That rule is one this course owns.'),
  ('riskchange', 'beginner', 'final', null, 42, 'How many different "Critical" figures can the OBODO register show across its four band-count populations?', '["4, one for each population", "3", "1", "2, inherent and residual"]'::jsonb, 1, 'The four figures are 5, 1, 4 and 1, and the two residual populations share the 1, which leaves 3 different values. Each is right for the question it answers.');
